export default function Main() {
return (
<div className='main'>
<div className="_container">
  <div className="main__row">
    <div className="main__row-left">
     
      <img src={foto1} alt="" />
      <img src={foto2} alt="" />
      </div>
     
   
    <div className="main__row-right">
   <div className="main__row-right-foto">
<img src={foto3} alt="" />
      <img src={foto4} alt="" />

   </div>
  .main__row-right_
    
     
    </div>
    
  </div>
</div>


 </div>
);
}
